-- Rotta Urbana — validate city/state/country service areas by coordinates.
-- The ride guard matched the address TEXT against the configured city/state.
-- Addresses come from different app versions and geocoders ("Avenida das
-- Figueiras 940", "Minha localização", POIs without the UF), so valid rides in
-- Sinop were rejected with "ride outside service area". The official IBGE
-- boundary of the configured area now decides by the ride coordinates; the
-- address text is only a fallback for an area without a stored boundary.
set search_path = public, extensions;

create table if not exists public.service_area_boundaries (
  scope text not null check (scope in ('city', 'state', 'country')),
  country_code text not null,
  state_code text not null default '',
  city_key text not null default '',
  name text not null,
  source text not null,
  geom geometry(MultiPolygon, 4326) not null,
  updated_at timestamptz not null default now(),
  primary key (scope, country_code, state_code, city_key)
);

create index if not exists service_area_boundaries_geom_idx
  on public.service_area_boundaries using gist (geom);

-- No policies: only the security definer functions below read or write it.
alter table public.service_area_boundaries enable row level security;
revoke all on public.service_area_boundaries from anon, authenticated;

create or replace function public.service_area_city_key(p_city text)
returns text
language sql stable set search_path = public, extensions
as $$
  select btrim(regexp_replace(lower(extensions.unaccent(coalesce(p_city, ''))), '[^a-z0-9]+', ' ', 'g'));
$$;

-- Called by the admin panel (service role) after the area is saved.
create or replace function public.set_service_area_boundary(
  p_scope text,
  p_country text,
  p_state text,
  p_city text,
  p_name text,
  p_source text,
  p_geojson text
)
returns void
language plpgsql security definer set search_path = public, extensions
as $$
declare
  v_geom geometry;
begin
  if p_scope not in ('city', 'state', 'country') then
    raise exception 'invalid service area scope';
  end if;
  v_geom := ST_Multi(ST_CollectionExtract(ST_MakeValid(ST_SetSRID(ST_GeomFromGeoJSON(p_geojson), 4326)), 3));
  if v_geom is null or ST_IsEmpty(v_geom) then
    raise exception 'invalid service area boundary';
  end if;

  insert into public.service_area_boundaries (scope, country_code, state_code, city_key, name, source, geom, updated_at)
  values (
    p_scope,
    upper(btrim(coalesce(p_country, 'BR'))),
    case when p_scope in ('city', 'state') then upper(btrim(coalesce(p_state, ''))) else '' end,
    case when p_scope = 'city' then public.service_area_city_key(p_city) else '' end,
    coalesce(nullif(btrim(p_name), ''), p_scope),
    coalesce(nullif(btrim(p_source), ''), 'manual'),
    v_geom,
    now()
  )
  on conflict (scope, country_code, state_code, city_key) do update
    set name = excluded.name,
        source = excluded.source,
        geom = excluded.geom,
        updated_at = now();
end;
$$;

-- true/false when the configured area can be decided; null only when the area
-- has no stored boundary and no address was given (the app then falls back to
-- its own reverse-geocoding check).
create or replace function public.service_area_allows_location(
  p_lng numeric,
  p_lat numeric,
  p_address text default null
)
returns boolean
language plpgsql stable security definer set search_path = public, extensions
as $$
declare
  s public.app_settings%rowtype;
  v_scope text;
  v_geom geometry;
begin
  select * into s from public.app_settings where id = 1;
  if not found or not coalesce(s.service_area_enabled, true) then
    return true;
  end if;
  if p_lng is null or p_lat is null
     or p_lng < -180 or p_lng > 180
     or p_lat < -90 or p_lat > 90 then
    return false;
  end if;

  v_scope := coalesce(s.service_area_scope, 'radius');
  if v_scope = 'radius' then
    return public.service_area_allows_point(p_lng, p_lat);
  end if;

  select b.geom into v_geom
    from public.service_area_boundaries b
   where b.scope = v_scope
     and b.country_code = upper(coalesce(nullif(btrim(s.service_area_country), ''), 'BR'))
     and b.state_code = case when v_scope in ('city', 'state')
                             then upper(coalesce(nullif(btrim(s.service_area_state), ''), 'MT')) else '' end
     and b.city_key = case when v_scope = 'city'
                           then public.service_area_city_key(coalesce(nullif(btrim(s.service_area_city), ''), 'Sinop')) else '' end;

  if v_geom is null then
    if p_address is null then
      return null;
    end if;
    return public.service_area_allows_address(p_address);
  end if;

  -- 30 m absorbs GPS noise exactly on the border line.
  return ST_DWithin(
    v_geom::geography,
    ST_SetSRID(ST_MakePoint(p_lng, p_lat), 4326)::geography,
    30
  );
end;
$$;

create or replace function public.enforce_ride_service_area()
returns trigger
language plpgsql security definer set search_path = public, extensions
as $$
declare
  s public.app_settings%rowtype;
begin
  if coalesce(public.service_area_allows_location(
       ST_X(new.origin::geometry)::numeric, ST_Y(new.origin::geometry)::numeric, coalesce(new.origin_address, '')), false)
     and coalesce(public.service_area_allows_location(
       ST_X(new.destination::geometry)::numeric, ST_Y(new.destination::geometry)::numeric, coalesce(new.destination_address, '')), false) then
    return new;
  end if;

  select * into s from public.app_settings where id = 1;
  raise exception 'ride outside service area: %',
    case coalesce(s.service_area_scope, 'radius')
      when 'country' then coalesce(s.service_area_country, 'BR')
      when 'state' then coalesce(s.service_area_state, 'MT')
      else coalesce(s.service_area_city, 'Sinop') || '/' || coalesce(s.service_area_state, 'MT')
    end;
end;
$$;

create or replace function public.update_ride_destination(
  p_ride_id uuid,
  p_dest_lat numeric,
  p_dest_lng numeric,
  p_dest_address text
)
returns public.rides
language plpgsql security definer set search_path = public, extensions
as $$
declare
  v_ride public.rides;
  v_dest geography;
  v_dist_km numeric;
  v_dur_min integer;
  v_price numeric;
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;
  if p_dest_lat is null or p_dest_lng is null
     or p_dest_lat < -90 or p_dest_lat > 90
     or p_dest_lng < -180 or p_dest_lng > 180 then
    raise exception 'invalid destination coordinates';
  end if;
  if nullif(btrim(p_dest_address), '') is null then
    raise exception 'destination address is required';
  end if;

  select * into v_ride
    from public.rides
   where id = p_ride_id
     and (driver_id = auth.uid() or passenger_id = auth.uid())
   for update;
  if not found then
    raise exception 'ride not found or not assigned to this user';
  end if;
  if v_ride.status not in ('driver_on_way', 'driver_arrived', 'in_progress') then
    raise exception 'destination can only be changed during an active ride';
  end if;

  if not coalesce(public.service_area_allows_location(p_dest_lng, p_dest_lat, p_dest_address), false) then
    raise exception 'destination outside service area';
  end if;

  v_dest := ST_SetSRID(ST_MakePoint(p_dest_lng, p_dest_lat), 4326)::geography;
  v_dist_km := round((ST_Distance(v_ride.origin, v_dest) / 1000.0)::numeric, 2);
  v_dur_min := greatest(1, ceil((v_dist_km / 30.0) * 60)::int);
  v_price := public.fare_estimate(v_ride.ride_type, v_dist_km, v_dur_min);

  update public.rides
     set destination = v_dest,
         destination_address = left(btrim(p_dest_address), 500),
         distance_km = v_dist_km,
         duration_min = v_dur_min,
         price = v_price
   where id = p_ride_id
   returning * into v_ride;

  return v_ride;
end;
$$;

revoke all on function public.set_service_area_boundary(text, text, text, text, text, text, text) from public, anon, authenticated;
grant execute on function public.set_service_area_boundary(text, text, text, text, text, text, text) to service_role;
revoke all on function public.service_area_allows_location(numeric, numeric, text) from public, anon;
grant execute on function public.service_area_allows_location(numeric, numeric, text) to authenticated, service_role;
revoke all on function public.update_ride_destination(uuid, numeric, numeric, text) from public, anon;
grant execute on function public.update_ride_destination(uuid, numeric, numeric, text) to authenticated, service_role;

comment on table public.service_area_boundaries is
  'Official boundaries (IBGE) of the admin-configured city/state/country service areas.';
comment on function public.service_area_allows_location is
  'Returns whether a coordinate is inside the admin-configured service area (boundary first, address text as fallback).';

